#define PI 3.1415
#define PI_2 6.28318
#define EPSILON 0.0005
#define MIN_DISTANCE 0.005
#define MAX_DISTANCE 30. 
#define PRECISION 0.001
#define MERGE_RADIUS 0.5
#define MAX_STEPS 155
#define BALL_RADIUS 3.
#define SHAPE_CYCLE 5.
#define BLINK_SPEED 3.

struct Material {
    vec3 ambientColor;
    vec3 diffuseColor;
    vec3 specularColor;
    float alpha;
};


Material gold() {
  vec3 aCol = 0.5 * vec3(0.7, 0.5, 0);
  vec3 dCol = 0.6 * vec3(0.7, 0.7, 0);
  vec3 sCol = 0.6 * vec3(1, 1, 1);
  float a = 25.;

  return Material(aCol, dCol, sCol, a);
}




