struct Surface {
    Material m; // material
    float d; // distance
};


vec3 lightEmissionColor = vec3(1., 1., 1.);

vec4 dblink(vec4 color, vec4 blinkColor) {
    float cycleTime = mod(iTime, SHAPE_CYCLE);
    vec4 res = color;
    if (cycleTime < BLINK_SPEED) {
       res = mix(blinkColor, color, cycleTime / BLINK_SPEED);   
    }

    return res;
}


float calculateSphereDistance(vec3 pr, vec3 c, float r, mat3 tm) {
    vec3 p = pr * tm;
    int shape = int(mod(mod(iTime / SHAPE_CYCLE, 6. * SHAPE_CYCLE), 6.));
    float distSphere = abs(length(p - c) - r) - 0.22; // abs and (-0.09) at the end is to make a shell instead of a sphere 

    float gyroidDistance;
    float cycleTime = mod(iTime, SHAPE_CYCLE);
    vec3 ve1;
    vec3 ve2;

    if (shape == 0) {
        vec3 pp1 = p * 1.;
        vec3 pp2 = p * 0.;
        ve1 = pp1.xxx;
        ve2 = pp1.yyy;

        if (cycleTime < BLINK_SPEED) {
            ve1 = mix(pp2.zxx, ve1, cycleTime / BLINK_SPEED);   
            ve2 = mix(pp2.zzz, ve2, cycleTime / BLINK_SPEED);   
        }
    } else if (shape == 1) {
        vec3 pp1 = p * 2.;
        vec3 pp2 = p * 1.;

        ve1 = pp1.xxy;
        ve2 = pp1.yyz;

        if (cycleTime < BLINK_SPEED) {
            ve1 = mix(pp2.xxx, ve1, cycleTime / BLINK_SPEED);   
            ve2 = mix(pp2.yyy, ve2, cycleTime / BLINK_SPEED);   
        }
    } else if (shape == 2) { 
        vec3 pp1 = p * 8.;
        vec3 pp2 = p * 2.;
        ve1 = pp1.xxy;
        ve2 = pp1.yyz;

        if (cycleTime < BLINK_SPEED) {
            ve1 = mix(pp2.xxy, ve1, cycleTime / BLINK_SPEED);   
            ve2 = mix(pp2.yyz, ve2, cycleTime / BLINK_SPEED);   
        }
    } else if (shape == 3) { 
        vec3 pp1 = p * 2.4;
        vec3 pp2 = p * 8.;
        ve1 = pp1.yxx;
        ve2 = pp1.xzy;

        if (cycleTime < BLINK_SPEED) {
            ve1 = mix(pp2.xxy, ve1, cycleTime / BLINK_SPEED);   
            ve2 = mix(pp2.yyz, ve2, cycleTime / BLINK_SPEED);   
        }
    } else if (shape == 4) { //
        vec3 pp1 = p * 4.0;
        vec3 pp2 = p * 2.4;
        ve1 = pp1.xyz;
        ve2 = pp1.yzx;

        if (cycleTime < BLINK_SPEED) {
            ve1 = mix(pp2.yxx, ve1, cycleTime / BLINK_SPEED);   
            ve2 = mix(pp2.xzy, ve2, cycleTime / BLINK_SPEED);   
        }
    } else if (shape == 5) {
        vec3 pp1 = p * 0.;
        vec3 pp2 = p * 4.0;
        ve1 = pp1.xxx; 
        ve2 = pp1.yyy;

        if (cycleTime < BLINK_SPEED) {
            ve1 = mix(pp2.xyz, ve1, cycleTime / BLINK_SPEED);   
            ve2 = mix(pp2.yzx, ve2, cycleTime / BLINK_SPEED);   
        }
    }

    gyroidDistance = abs(dot(sin(ve1), cos(ve2)) / 10.) - 0.04;


    return max(distSphere, gyroidDistance);
}

// shape - which type of 'gyroid' we render
Surface sdSphere(vec3 pr, vec3 c, float r, Material m, mat3 tm) {
    return Surface(m, calculateSphereDistance(pr, c, r, tm));
}



Surface sdFloor(vec3 p, float y, Material m) {
