Surface minSurface(Surface s1, Surface s2) {
    Surface res = s1;
    if (res.d > s2.d) res = s2;
    return res;
}



Surface scene(vec3 pr) {
    float sTime = iTime / 2.;
    Surface sphere1 = sdSphere(pr, vec3(0., 0., 0.), BALL_RADIUS, gold(), rotateZ(sTime)); 
    Surface res = sphere1;
    res = minSurface(sdFloor(pr, 4.5, checkboard(pr)), res);

    return res;
}




// vector normal to sphere with cener c and radius r
vec3 calcNormal(vec3 p) {
  vec2 e = vec2(1.02, -1.02) * EPSILON;
  return normalize(
    e.xyy * scene(p + e.xyy).d +
    e.yyx * scene(p + e.yyx).d +
    e.yxy * scene(p + e.yxy).d +
    e.xxx * scene(p + e.xxx).d);
}


struct RaymarchRes {
    Surface s;
    vec3 p; // surface hit point
    float d; // distance
};


RaymarchRes raymarch(vec3 ro, vec3 rd) {
    float t = MIN_DISTANCE; 
    RaymarchRes res;
    res.d = MAX_DISTANCE;

    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + t * rd;
        Surface sf = scene(p); 
        t += sf.d;

        if (sf.d < PRECISION) { // we hit the surface at point p
            //vec3 normalToSurfaceVector = calcNormal(p);
            //res.l = clamp(dot(normalToSurfaceVector, normalize(lightVector - p)), 0.1, 1.);
            res.p = p;
            res.s = sf;
            break;
        } else if (sf.d > MAX_DISTANCE) break; // we did not hit anything but are to far away from camera 
            //t += sf.d; // we did not hit anything, keep on trying
    }

    res.d = t;
    return res;
}

mat3 camera(vec3 cameraPos, vec3 lookAtPoint) {
    vec3 cd = normalize(lookAtPoint - cameraPos);
    vec3 cr = normalize(cross(vec3(0, 1, 0), cd));
    vec3 cu = normalize(cross(cd, cr));

    return mat3(-cr, cu, -cd);
}

vec3 calculateCameraPosition(vec3 lookAt, vec2 uv) {

    vec3 ro = vec3(0, 0.9, -8.); 

  //  float cameraRadius = 10.;
  //  ro.x = -0.5 + cameraRadius * cos(cameraTime) + lookAt.x; 
  //  ro.z = 2.5 + cameraRadius * sin(cameraTime) / 3. + lookAt.z; 
  //  ro.y = sin(cameraTime + sin(cameraTime)) * 5. + 7.;

    return ro;
}

vec3 calculateLightPosition(vec3 lookAt) {
    vec3 lightVector = vec3(0., 0., 0.);
    return lightVector;
}


float calcShadow(in vec3 ro, vec3 rd){ 
    //float t = MIN_DISTANCE; 
    float res = 1.0;
    float t = 0.;

    ro += rd * MIN_DISTANCE * 2.;

    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + t * rd;
        Surface sf = scene(p); 

        if (abs(sf.d) < PRECISION) { // we hit the surface at point p so we have not reached light source
            res = 0.;
            break;
            //return 1.;//abs(sf.d);
        } else if (sf.d > MAX_DISTANCE) break; // we did not hit anything but are to far away from camera 
            t += sf.d;
            res = 1.;
    }

    return res;
}

vec3 calculateLight(vec2 fragCoord, RaymarchRes rr, vec3 rd, vec3 lo, vec3 backgroundColor) {
    vec3 normalToSurfaceVector = calcNormal(rr.p);
    vec3 l = -normalize(-lo + rr.p); // light direction
    vec3 color = rr.s.m.ambientColor; 
    float shadowMask = 1.0;
    float distanceFromLight = length(rr.p);
    vec3 lightColor = lightEmissionColor;

    // replace  rr.d with a center of the ball if NOT (0, 0, 0)
    if (distanceFromLight > BALL_RADIUS * 1.1) { // we are NOT inside the ball (where we do NOT calculate shadow) rr.d works only if the ball's center is (0,0,0)
        vec3 newRayOrigin = rr.p + normalToSurfaceVector * PRECISION * 2. ;
        shadowMask = calcShadow(newRayOrigin, l);
        //float sTime = iTime / 2.;
        //shadowMask = calculateSphereDistance(-lo, vec3(0., 0., 0.), BALL_RADIUS, rotateZ(sTime)) / BALL_RADIUS;
        //color += rr.s.m.diffuseColor * shadowMask;
        //color *= 1.3;
        color += vec3(0.7, 0.7, 0.) * 0.6 * 0.7 * shadowMask;
        //color = rr.s.m.diffuseColor;
    } else { // we are inside the ball

        // what we are doing here is we are adding a bit of light to outisde part of the ball that normally would be black as is not lighted at all
        if (distanceFromLight > BALL_RADIUS) {
            l = -l;
            lightColor = vec3(0.5);
            rr.s.m.diffuseColor = lightColor;
            rr.s.m.specularColor = lightColor;
        }

        vec3 diffusion = clamp(dot(l, normalToSurfaceVector), 0., 1.) * rr.s.m.diffuseColor * lightColor; // diffusion light
        float dotRV = clamp(dot(reflect(l, normalToSurfaceVector), rd), 0., 1.);
        vec3 specular =  clamp(pow(dotRV, rr.s.m.alpha), 0., 1.) * rr.s.m.specularColor * lightColor;; // specular light
        color += (specular + diffusion);// * shadowMask;
//        color = vec3(1.);
    }


    color = clamp(color, 0., 1.);

    // gamma correction
    float shadowGammaCorr = 0.8;
    float lightGammaCorr = 1.0;
    float shadowTreshold = 0.3;
    color = mix(pow(color, vec3(1.0 / shadowGammaCorr)),
            pow(color, vec3(1.0 / lightGammaCorr)), smoothstep(shadowTreshold, shadowTreshold + 0.1, (color.r + color.g + color.b) / 2.));

    vec2 q = fragCoord.xy / iResolution.xy;
    color = vec3(color * pow(20. * q.x * q.y * (1.0 - q.x) * (1.0 - q.y), 0.5)); // vigniete
    color = mix(color, backgroundColor, 1.0 - exp(-0.00004*rr.d*rr.d*rr.d)); // fog to background


/*
    // gamma correction basic

    float gammaCorr = 0.45;
    color = pow(color, vec3(0.45));
  */  
    return color;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
    vec3 lookAt = vec3(0.0,0.5, -4.);
    vec3 ro = calculateCameraPosition(lookAt, uv);
    vec3 rd = camera(ro, lookAt) * normalize(vec3(uv, -1.));
    vec3 lo = calculateLightPosition(lookAt);
    vec4 backgroundColor = vec4(mix(vec3(0., 0.1, .2), vec3(0., 0., 0.), uv.y) * 1.8, 1.0);
    RaymarchRes rr = raymarch(vec3(ro.x, ro.y, ro.z), rd);
    fragColor = (rr.d < MAX_DISTANCE) ? vec4(calculateLight(fragCoord, rr, rd, lo, backgroundColor.xyz), 1.0) : backgroundColor;    
    //fragColor = blink(fragColor, vec4(1.,1., 1., 0.));
}

mat3 rotateX(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(1, 0, 0),
        vec3(0, c, -s),
        vec3(0, s, c)
    );
}

mat3 rotateY(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, 0, s),
        vec3(0, 1, 0),
        vec3(-s, 0, c)
    );
}

mat3 rotateZ(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, -s, 0),
        vec3(s, c, 0),
        vec3(0, 0, 1)
    );
}
mat3 identity() {
    return mat3(
        vec3(1, 0, 0),
        vec3(0, 1, 0),
        vec3(0, 0, 1)
    );
}
